Script:
today = frappe.utils.getdate(frappe.utils.today())
now = frappe.utils.now_datetime()

events = frappe.get_all(
    "College Event",
    filters={"approval_status": "Approved", "status": ["!=", "Cancelled"]},
    fields=["name"]
)

for e in events:
    doc = frappe.get_doc("College Event", e.name)
    changed = False

    if doc.registration_required:
        if doc.registration_status == "Not Started" and doc.registration_start and doc.registration_end:
            if now >= doc.registration_start and now <= doc.registration_end:
                doc.registration_status = "Open"
                changed = True

                eligible_filters = {"status": "Active"}
                if doc.audience == "Specific Program" and doc.program:
                    eligible_filters["program"] = doc.program
                if doc.audience == "Specific Department" and doc.department:
                    eligible_filters["department"] = doc.department

                students = []
                if doc.audience in ("All Students", "Specific Program", "Specific Department"):
                    students = frappe.get_all("Admission Student", filters=eligible_filters, fields=["email"])

                for s in students:
                    if s.email and frappe.db.exists("User", s.email):
                        frappe.get_doc({
                            "doctype": "Notification Log",
                            "subject": "Registration Open: " + doc.event_name,
                            "for_user": s.email,
                            "type": "Alert",
                            "document_type": "College Event",
                            "document_name": doc.name
                        }).insert(ignore_permissions=True)

        elif doc.registration_status == "Open" and doc.registration_end and now > doc.registration_end:
            doc.registration_status = "Closed"
            changed = True

    if doc.starts_on:
        event_date = frappe.utils.getdate(doc.starts_on)
        if event_date == frappe.utils.add_days(today, 1):
            for row in (doc.registrations or []):
                if row.status == "Registered":
                    student_email = frappe.db.get_value("Admission Student", row.student, "email")
                    if student_email and frappe.db.exists("User", student_email):
                        already_sent = frappe.db.exists(
                            "Notification Log",
                            {"subject": "Reminder: " + doc.event_name + " is tomorrow", "for_user": student_email}
                        )
                        if not already_sent:
                            frappe.get_doc({
                                "doctype": "Notification Log",
                                "subject": "Reminder: " + doc.event_name + " is tomorrow",
                                "for_user": student_email,
                                "type": "Alert",
                                "document_type": "College Event",
                                "document_name": doc.name
                            }).insert(ignore_permissions=True)

    if doc.attendance_required and doc.starts_on:
        event_date = frappe.utils.getdate(doc.starts_on)
        if event_date == today and not doc.attendance_records:
            for row in (doc.registrations or []):
                if row.status == "Registered":
                    doc.append("attendance_records", {
                        "student": row.student,
                        "attendance": "Absent"
                    })
            changed = True

    if changed:
        doc.save(ignore_permissions=True)

registered = [r for r in (doc.registrations or []) if r.status == "Registered"]
doc.current_participants = len(registered)

if doc.registration_required and doc.maximum_participants:
    if doc.current_participants >= doc.maximum_participants and doc.registration_status == "Open":
        doc.registration_status = "Closed"

if doc.approval_status == "Approved" and not doc.approved_on:
    doc.approved_by = frappe.session.user
    doc.approved_on = frappe.utils.now()

    already_linked = frappe.db.exists(
        "Academic Calendar Event",
        {"target_doctype": "College Event", "target_document": doc.name}
    )
    if not already_linked:
        calendar = None
        if doc.academic_year:
            matches = frappe.get_all(
                "Academic Calendar",
                filters={"academic_year": doc.academic_year, "status": ["in", ["Approved", "Active"]]},
                fields=["name"], limit=1
            )
            if matches:
                calendar = matches[0].name
        if not calendar:
            fallback = frappe.get_all(
                "Academic Calendar",
                filters={"status": ["in", ["Approved", "Active"]]},
                fields=["name"], limit=1
            )
            if fallback:
                calendar = fallback[0].name

        if calendar:
            cal_doc = frappe.get_doc("Academic Calendar", calendar)
            event_date = frappe.utils.getdate(doc.starts_on) if doc.starts_on else None
            end_date = frappe.utils.getdate(doc.ends_on) if doc.ends_on else event_date
            cal_doc.append("events", {
                "activity": "College Event",
                "start_date": event_date,
                "end_date": end_date,
                "auto_execute": 0,
                "target_doctype": "College Event",
                "target_document": doc.name,
                "status": "Pending"
            })
            cal_doc.save(ignore_permissions=True)

if doc.certificate_required:
    for row in (doc.attendance_records or []):
        if row.attendance == "Present" and not row.certificate_issued:
            row.certificate_issued = 1
            existing_cert = frappe.db.exists(
                "Event Certificate", {"event": doc.name, "student": row.student}
            )
            if not existing_cert:
                cert = frappe.get_doc({
                    "doctype": "Event Certificate",
                    "event": doc.name,
                    "student": row.student,
                    "issue_date": frappe.utils.today(),
                    "status": "Generated"
                })
                cert.insert(ignore_permissions=True)

                student_email = frappe.db.get_value("Admission Student", row.student, "email")
                if student_email and frappe.db.exists("User", student_email):
                    frappe.get_doc({
                        "doctype": "Notification Log",
                        "subject": "Certificate Ready: " + doc.event_name,
                        "for_user": student_email,
                        "type": "Alert",
                        "document_type": "Event Certificate",
                        "document_name": cert.name
                    }).insert(ignore_permissions=True)

verification_required_stages = False

for r in (doc.recommendations or []):
    if r.status == "Recommended":
        verification_required_stages = True

for a in (doc.approvals or []):
    if a.status == "Approved":
        verification_required_stages = True

if verification_required_stages:
    is_verified = frappe.db.exists(
        "Scholarship Verification",
        {"application": doc.name, "verification_status": "Verified"}
    )
    if not is_verified:
        frappe.throw(
            "Cannot record a Recommendation or Approval until this application's "
            "Scholarship Verification status is 'Verified'. Please complete document "
            "verification first."
        )

if doc.status not in ("Sanctioned", "Rejected"):
    has_not_recommended = False
    has_recommended = False
    has_approval_rejected = False
    has_approved = False

    for row in doc.recommendations:
        if row.status == "Not Recommended":
            has_not_recommended = True
        if row.status == "Recommended":
            has_recommended = True

    for row in doc.approvals:
        if row.status == "Rejected":
            has_approval_rejected = True
        if row.status == "Approved":
            has_approved = True

    if has_not_recommended or has_approval_rejected:
        doc.status = "Rejected"
    elif has_approved:
        doc.status = "Approved"
    elif has_recommended:
        doc.status = "Recommended"

app_status = frappe.db.get_value("Scholarship Application", doc.application, "status")

if app_status == "Submitted":
    frappe.db.set_value("Scholarship Application", doc.application, "status", "Under Verification")

scheme_name = frappe.form_dict.get("scheme")

if not scheme_name:
    frappe.response["message"] = []
else:
    scheme = frappe.get_doc("Scholarship Scheme", scheme_name)
    income_limit = scheme.income_limit
    attendance_requirement = scheme.attendance_requirement

    students = frappe.get_all(
        "Admission Student",
        fields=["name", "annual_family_income", "attendance_percentage"]
    )

    eligible = []
    for s in students:
        income_ok = True
        attendance_ok = True

        if income_limit:
            if not s.annual_family_income or s.annual_family_income > income_limit:
                income_ok = False

        if attendance_requirement:
            if not s.attendance_percentage or s.attendance_percentage < attendance_requirement:
                attendance_ok = False

        if income_ok and attendance_ok:
            eligible.append({
                "student": s.name,
                "income": s.annual_family_income,
                "attendance": s.attendance_percentage
            })

    frappe.response["message"] = eligible

total = len(doc.document_items)
verified = 0
missing = 0
rejected = 0

for row in doc.document_items:
    if row.verification_status == "Verified":
        verified = verified + 1
    elif row.verification_status == "Missing":
        missing = missing + 1
    elif row.verification_status == "Rejected":
        rejected = rejected + 1

doc.total_documents = total
doc.verified_documents = verified
doc.missing_documents = missing

if total == 0:
    doc.verification_status = "Pending"
elif rejected > 0:
    doc.verification_status = "Rejected"
elif verified == total:
    doc.verification_status = "Verified"
elif verified > 0:
    doc.verification_status = "Partially Verified"
else:
    doc.verification_status = "Pending"

old_doc = doc.get_doc_before_save()

if old_doc and old_doc.status != "Submitted" and doc.status == "Submitted":
    existing = frappe.db.exists("Scholarship Verification", {"application": doc.name})

    if existing:
        frappe.msgprint(f"Verification record already exists for this application: {existing}")
    elif not doc.documents:
        frappe.msgprint("No documents attached - no verification record created. Add documents before submitting.")
    else:
        academic_year = frappe.db.get_value("Scholarship Scheme", doc.scheme, "academic_year")

        items = []
        for row in doc.documents:
            items.append({
                "document_type": row.document_type,
                "required": 1,
                "submitted": 1,
                "verified": 0,
                "verification_status": "Pending"
            })

        ver = frappe.get_doc({
            "doctype": "Scholarship Verification",
            "application": doc.name,
            "academic_year": academic_year,
            "document_items": items
        })
        ver.insert(ignore_permissions=True)
        frappe.msgprint(f"Created verification record {ver.name} with {len(doc.documents)} document(s).")

if doc.status == "Completed":
    if not frappe.db.exists("Alumni", {"admission_student": doc.name}):
        alumni = frappe.new_doc("Alumni")
        alumni.admission_student = doc.name
        alumni.graduation_date = frappe.utils.nowdate()
        alumni.created_from_graduation = 1
        alumni.insert(ignore_permissions=True)

        if doc.student:
            frappe.db.set_value("Admission Student", doc.student, "status", "Alumni")

        frappe.msgprint("Alumni record created: " + alumni.name)
